abhinav_26_27 = {
    'hi': '।।7.26--7.27।। श्री अभिनवगुप्त कहते हैं: हे अर्जुन ! मैं अतीत (बीते हुए), वर्तमान और भविष्य में होने वाले सभी प्राणियों को जानता हूँ, किंतु मुझे कोई नहीं जानता। हे भरतवंश श्रेष्ठ परंतप ! इच्छा (राग) और द्वेष से उत्पन्न द्वन्द्व-मोह के कारण इस संसार के सम्पूर्ण प्राणी सृष्टि-काल से ही अज्ञानमयी मोह को प्राप्त हो रहे हैं।',
    'en': '7.26--7.27 Sri Abhinavagupta states: O Arjuna, I know the beings of the past, present, and future, but Me no one knows. O Bharata, scorcher of foes, by the delusion of opposites arising from desire and aversion, all beings fall into deep delusion at the time of creation.',
    'be': '৭.২৬--৭.২৭ শ্রী অভিনবগুপ্ত বলেছেন: হে অর্জুন! আমি অতীত (গত হওয়া), বর্তমান ও ভবিষ্যতে হওয়া সব প্রাণীকে জানি, কিন্তু আমাকে কেউ জানে না। হে ভারতবংশ শ্রেষ্ঠ পরন্তপ! ইচ্ছা (রাগ) ও দ্বেষ থেকে উৎপন্ন দ্বন্দ্ব-মোহের কারণে এই সংসারের সম্পূর্ণ প্রাণী সৃষ্টি-কাল থেকেই অজ্ঞানময়ী মোহকে প্রাপ্ত হচ্ছে।',
    'ka': '೭.೨೬--೭.೨೭ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಹೇ ಅರ್ಜುನ! ನಾನು ಗತಕಾಲದ, ವರ್ತಮಾನದ ಹಾಗೂ ಭವಿಷ್ಯತ್ತಿನ ಸಮಸ್ತ ಪ್ರಾಣಿಗಳನ್ನು ಅರಿಯುತ್ತೇನೆ, ಆದರೆ ನನ್ನನ್ನು ಯಾರೂ ಅರಿಯುವುದಿಲ್ಲ. ಹೇ ಭರತಶ್ರೇಷ್ಠ ಪರಂತಪ! ಇಚ್ಛೆ (ರಾಗ) ಹಾಗೂ ದ್ವೇಷಗಳಿಂದ ಉತ್ಪನ್ನವಾದ ದ್ವಂದ್ವಮೋಹದ ಕಾರಣದಿಂದ ಈ ಸಂಸಾರದಲ್ಲಿ ಸಮಸ್ತ ಪ್ರಾಣಿಗಳೂ ಸೃಷ್ಟಿಕಾಲದಿಂದಲೇ ಅಜ್ಞಾನಮಯಿ ಮೋಹವನ್ನು ಪಡೆಯುತ್ತಿದ್ದಾರೆ'
}

abhinav_29_30 = {
    'hi': '।।7.29--7.30।। श्री अभिनवगुप्त कहते हैं: जो मेरे आश्रित होकर जरा (वृद्धावस्था) और मरण से मोक्ष पाने के लिए यत्न करते हैं, वे उस परब्रह्म को, सम्पूर्ण अध्यात्म को और सर्व कर्म को जानते हैं। जो आधिभूत, आधिदैव और आधियज्ञ के सहित मुझे जानते हैं, वे समाहित-चित्त योगी मरण-काल में भी मुझे ही जानते हैं (मुझमें ही लीन होते हैं)।',
    'en': '7.29--7.30 Sri Abhinavagupta states: Those who, taking refuge in Me, strive for liberation from old age and death, know that Supreme Brahman, the whole Self-knowledge (Adhyatma), and all Karma. Those who know Me with Adhibhuta, Adhidaiva, and Adhiyajna, with mind steadfast in Yoga, comprehend Me even at the hour of death.',
    'be': '৭.২৯--৭.৩০ শ্রী অভিনবগুপ্ত বলেছেন: যে আমার আশ্রিত হয়ে জরা (বার্ধক্য) ও মরণ থেকে মোক্ষ পাওয়ার জন্য যত্ন করে, তারা সেই পরব্রহ্মকে, সম্পূর্ণ অধ্যাত্মকে এবং সর্ব কর্মকে জানে। যে আধিভূত, আধিদৈব ও আধিয়জ্ঞের সহ আমাকে জানে, সেই সমাহিত-চিত্ত যোগী মরণ-কালেও আমাকেই জানে (আমাতেই লীন হয়)।',
    'ka': '೭.೨೯--೭.೩೦ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಯಾರು ನನ್ನನ್ನಾಶ್ರಯಿಸಿ ಜರಾಮರಣಗಳಿಂದ ಮುಕ್ತಿಯನ್ನು ಪಡೆಯಲು ಯತ್ನಿಸುತ್ತಾರೋ, ಅವರು ಆ ಪರಬ್ರಹ್ಮನನ್ನು, ಸಮಸ್ತ ಅಧ್ಯಾತ್ಮವನ್ನೂ ಸರ್ವ ಕರ್ಮವನ್ನೂ ಅರಿಯುತ್ತಾರೆ. ಯಾರು ಆಧಿಭೂತ, ಆಧಿಧೈವ ಹಾಗೂ ಆಧಿಯಜ್ಞಗಳೊಂದಿಗೆ ನನ್ನನ್ನು ಅರಿಯುತ್ತಾರೋ, ಅಂತಹ ಸಮಾಹಿತಚಿತ್ತರಾದ ಯೋಗಿಗಳು ಮರಣಕಾಲದಲ್ಲೂ ನನ್ನನ್ನೇ ಅರಿಯುತ್ತಾರೆ (ನನ್ನಲ್ಲೇ ಲೀನವಾಗುತ್ತಾರೆ)'
}

